insert into public.subjects (code,name) values ('BIO','Biology'),('CHEM','Chemistry'),('PHY','Physics'),('ENG','English'),('LR','Logical Reasoning');
insert into public.questions (subject_id, slo_reference, question, options, correct_answer_index, explanation, difficulty) values ((select id from public.subjects where code='BIO'), '1.1', 'Two viral isolates both have RNA genomes, but one genome is single-stranded and the other is double-stranded. Which feature distinguishes them in this classification?', '["The number of strands in the genome", "The temperature of the host organism", "The number of cells in the host tissue", "The location where the sample was collected"]'::jsonb, 0, 'Viral genomes can be distinguished by whether they are single-stranded or double-stranded.', 'easy');
insert into public.questions (subject_id, slo_reference, question, options, correct_answer_index, explanation, difficulty) values ((select id from public.subjects where code='BIO'), '3.3', 'A lake warms more slowly than nearby dry ground on a sunny afternoon. Which property of water best explains this difference?', '["Its high specific heat capacity", "Its ability to form ionic bonds with soil", "Its low density in the liquid state", "Its rapid evaporation at all temperatures"]'::jsonb, 0, 'Water can absorb substantial heat before its temperature changes appreciably because it has a high specific heat capacity.', 'easy');
insert into public.questions (subject_id, slo_reference, question, options, correct_answer_index, explanation, difficulty) values ((select id from public.subjects where code='BIO'), '3.9', 'A model shows two DNA strands winding around a shared axis. Which description best names this arrangement?', '["A double helix", "A phospholipid bilayer", "A branched polysaccharide", "A single amino-acid chain"]'::jsonb, 0, 'The Watson–Crick model describes DNA as two strands arranged in a double-helical structure.', 'easy');
insert into public.questions (subject_id, slo_reference, question, options, correct_answer_index, explanation, difficulty) values ((select id from public.subjects where code='BIO'), '4.2', 'A cell''s DNA is enclosed by a membrane-bound nucleus. Which broad cell category does this observation support?', '["A prokaryotic cell", "A eukaryotic cell", "A virus particle", "A bacterial endospore"]'::jsonb, 1, 'Eukaryotic cells have DNA enclosed in a membrane-bound nucleus; prokaryotic cells do not.', 'easy');
insert into public.questions (subject_id, slo_reference, question, options, correct_answer_index, explanation, difficulty) values ((select id from public.subjects where code='BIO'), '6.3', 'An experiment changes temperature while keeping pH and enzyme amount constant. Which factor is being tested for its effect on enzyme action?', '["Temperature", "Substrate identity", "Cell size", "Light intensity"]'::jsonb, 0, 'Because temperature is the variable changed while the other stated conditions are controlled, the experiment tests temperature''s effect on enzyme action.', 'easy');
